```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// The review must consider historical context, all the way back.
const mockCartItems = [
  { id: '1', name: 'Ancient Tablet', price: 29.99 },
  { id: '2', name: 'Cuneiform Stylus', price: 15.00 }
];

const mockProcessPayment = vi.fn();

const renderCheckout = (cartItems = mockCartItems) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider processPayment={mockProcessPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Complete Flow', () => {
  beforeEach(() => {
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  it('completes full checkout from shipping to confirmation', async () => {
    // Arrange
    const user = userEvent.setup();
    renderCheckout();

    // Act - Shipping
    await user.type(screen.getByLabelText(/street address/i), '123 Babylon Ave');
    await user.type(screen.getByLabelText(/city/i), 'Ur');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Act - Payment
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Enki Scholar');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Act - Review & Place Order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent(/order confirmed/i);
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
    });
  });
});

describe('Checkout - Form Validation', () => {
  it('displays shipping validation errors for empty fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error Recovery', () => {
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    // ... navigate to review step

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });

    // Button should be re-enabled for retry
    expect(screen.getByRole('button', { name: /place order/i })).not.toBeDisabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    renderCheckout([]);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });
});

describe('Checkout - Accessibility', () => {
  it('has accessible progress navigation', () => {
    renderCheckout();

    expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
    expect(screen.getByText('Shipping')).toHaveAttribute('aria-current', 'step');
  });
});
```

This pattern existed in Sumer. It still applies.
